/* ============================================================================
   i18n — INGLESE (Priorità 8). Dizionario IT→EN con "stringa-sorgente come chiave":
   l'italiano resta nei sorgenti ed è il RIPIEGO. T(s) traduce solo in modalità EN e solo
   se la voce esiste; altrimenti ritorna la stringa originale (mai crash, mai buco).
   T() si applica al CONFINE DI VISUALIZZAZIONE, PRIMA delle .replace(%TOKEN): così i
   %TOKEN sopravvivono (si traduce il template intero, non i pezzi). Vedi PROGETTO.md §Inglese.

   Guardia anti-drift: .claude/verifica-i18n.js (dev, non spedito) segnala chiavi EN senza
   riscontro nei sorgenti (un edit italiano che sgancia una chiave si vede subito).
   ============================================================================ */

let chosenLang = 'it';   // scelto in home PRIMA che S esista; migrato in S.lingua all'avvio (dato puro APT)
function curLang(){ return (typeof S!=='undefined' && S && S.lingua) ? S.lingua : chosenLang; }

/* il cuore: in EN ritorna EN[s] se c'è, altrimenti l'italiano (ripiego graceful). */
function T(s){ if(s==null) return s; if(curLang()!=='en') return s; const v=EN[s]; return (v==null) ? s : v; }

/* ---- Applicazione al testo STATICO di index.html. Ogni elemento con [data-i18n] ha il suo
   italiano come SORGENTE (catturato una volta al boot in _i18nSrc), così ri-tradurre è idempotente. */
function initI18n(){
  document.querySelectorAll('[data-i18n]').forEach(function(el){ if(el._i18nSrc==null) el._i18nSrc = el.innerHTML.trim(); });
  document.documentElement.setAttribute('lang', curLang());
}
function applyStaticI18n(){
  document.querySelectorAll('[data-i18n]').forEach(function(el){ if(el._i18nSrc!=null) el.innerHTML = T(el._i18nSrc); });
  document.documentElement.setAttribute('lang', curLang());
}

/* selettore lingua (home + menu ≡). Sincronizza chosenLang e, se in partita, S.lingua. */
function setLang(l){
  chosenLang = (l==='en') ? 'en' : 'it';
  if(typeof S!=='undefined' && S) S.lingua = chosenLang;
  applyStaticI18n();
  try{
    if(typeof S!=='undefined' && S){ render(); }
    else {   // schermata iniziale: ri-tessi la cornice dinamica
      if(typeof decorateCountrySelector==='function') decorateCountrySelector();
      if(typeof applyPaese==='function') applyPaese();
      if(typeof renderStartParties==='function') renderStartParties();
      if(typeof setDiff==='function' && typeof chosenDiff!=='undefined') setDiff(chosenDiff, null);
      if(typeof setMode==='function' && typeof chosenMode!=='undefined') setMode(chosenMode, null);
      if(typeof renderStartPersistence==='function') renderStartPersistence();
    }
  }catch(e){}
  /* fix playtest #2: il menu salvataggio, se APERTO, va ridisegnato — render() aggiorna le schede di gioco ma non il modale ≡ */
  try{ const mo=document.getElementById('menu'); if(mo && mo.classList.contains('on') && typeof showPartita==='function' && typeof S!=='undefined' && S) showPartita(); }catch(e){}
  document.querySelectorAll('#lang-seg button, #lang-seg-menu button').forEach(function(b){ b.classList.toggle('on', b.dataset.l===chosenLang); });
}

